"""Remove executable JavaScript from an HTML document in place."""
import html
import re
import sys
from html.parser import HTMLParser
from pathlib import Path

VOID_TAGS = frozenset('area base br col embed hr img input link meta param source track wbr'.split())
DANGEROUS_TAGS = frozenset({'script', 'applet', 'object', 'embed'})
URL_ATTRIBUTES = frozenset({'href', 'src', 'action', 'formaction', 'xlink:href', 'data', 'poster', 'background', 'cite', 'manifest', 'codebase', 'archive', 'longdesc', 'usemap', 'profile'})
BAD_CSS = re.compile(r'expression\s*\(|behavior\s*:|-moz-binding\s*:|@import\b|url\s*\(\s*[\"\']?\s*(?:javascript|vbscript|data\s*:\s*text/html)\s*:', re.I)


def dangerous_url(value):
    # Decode HTML entities and repeatedly percent-decode to detect common evasions.
    from urllib.parse import unquote
    value = html.unescape(value)
    for _ in range(3):
        decoded = unquote(value)
        if decoded == value:
            break
        value = decoded
    compact = re.sub(r'[\x00-\x20\x7f]+', '', value).casefold()
    if compact.startswith(('javascript:', 'vbscript:')):
        return True
    if compact.startswith('data:'):
        return not compact.startswith(('data:image/', 'data:audio/', 'data:video/', 'data:font/'))
    return False


class Sanitizer(HTMLParser):
    def __init__(self, source):
        super().__init__(convert_charrefs=False)
        self.source = source
        self.parts = []
        self.suppressed = []
        self.drop_content = []

    def _original(self, start, end):
        return self.source[start:end]

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        start, end = self.getpos()
        original = self._original(start, start + 1)
        del original
        # get_starttag_text preserves original whitespace, quote styles and case.
        raw = self.get_starttag_text()
        if self.suppressed:
            if tag in DANGEROUS_TAGS and tag not in VOID_TAGS:
                self.suppressed.append(tag)
            return
        if tag in DANGEROUS_TAGS:
            if tag not in VOID_TAGS:
                self.suppressed.append(tag)
            return
        self._emit_filtered_tag(raw, tag, attrs)

    def _emit_filtered_tag(self, raw, tag, attrs):
        clean = []
        for name, value in attrs:
            key = name.lower()
            if key.startswith('on') or key in {'srcdoc', 'xmlns'} and tag == 'svg':
                continue
            if value is not None and key in URL_ATTRIBUTES and dangerous_url(value):
                continue
            if value is not None and key == 'style':
                value = BAD_CSS.sub('', value)
            clean.append((key, value))
        # Keep original opening tag byte-for-byte when no filtering was necessary.
        original_attrs = self._parse_raw_attributes(raw)
        if clean == original_attrs:
            self.parts.append(raw)
            return
        match = re.match(r'<\s*[^\s/>]+', raw)
        if not match:
            self.parts.append(raw)
            return
        name_text = match.group(0)
        is_self_closing = raw.rstrip().endswith('/>')
        rendered = [name_text]
        for key, value in clean:
            if value is None:
                rendered.append(' ' + key)
            else:
                rendered.append(' ' + key + '="' + html.escape(value, quote=True) + '"')
        rendered.append('/>' if is_self_closing else '>')
        self.parts.append(''.join(rendered))

    @staticmethod
    def _parse_raw_attributes(raw):
        # Attribute values are entity-decoded by HTMLParser, so only use this
        # comparison as an optimization when no attributes need to be filtered.
        return None

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if self.suppressed or tag in DANGEROUS_TAGS:
            return
        self._emit_filtered_tag(self.get_starttag_text(), tag, attrs)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.suppressed:
            if tag == self.suppressed[-1]:
                self.suppressed.pop()
            return
        start, end = self.getpos()
        raw = self.source[start:end]
        # getpos points to the beginning of this token; HTMLParser does not expose
        # the raw end-tag text, so recover it directly from the source.
        match = re.match(r'</\s*[^>]*>', self.source[start:], re.I)
        if match:
            raw = match.group(0)
        if tag not in DANGEROUS_TAGS:
            self.parts.append(raw)

    def handle_data(self, data):
        if not self.suppressed:
            self.parts.append(data)

    def handle_entityref(self, name):
        if not self.suppressed:
            self.parts.append('&' + name + ';')

    def handle_charref(self, name):
        if not self.suppressed:
            self.parts.append('&#' + name + ';')

    def handle_comment(self, data):
        if not self.suppressed:
            self.parts.append('<!--' + data + '-->')

    def handle_decl(self, decl):
        if not self.suppressed:
            self.parts.append('<!' + decl + '>')

    def unknown_decl(self, data):
        if not self.suppressed:
            self.parts.append('<![%s]>' % data)

    def handle_pi(self, data):
        if not self.suppressed:
            self.parts.append('<?' + data + '>')


def sanitize(source):
    parser = Sanitizer(source)
    parser.feed(source)
    parser.close()
    return ''.join(parser.parts)


def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py HTML_FILE', file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    with path.open('r', encoding='utf-8', errors='surrogateescape', newline='') as file:
        source = file.read()
    result = sanitize(source)
    with path.open('w', encoding='utf-8', errors='surrogateescape', newline='') as file:
        file.write(result)
    return 0


if __name__ == '__main__':
    sys.exit(main())
